// Census data generated by npm run build:census.
import stateCensus from "./census/states.json";
import districtCensus from "./census/districts.json";
import censusMeta from "./census/meta.json";

// Which census the dashboard is showing.
export const CENSUS_YEAR = censusMeta.year;
export const CENSUS_LABEL = censusMeta.label;

// Dashboard level options.
export const levelOptions = ["State / UT", "District"];

// Parameters generated from the census configuration.
const parameterOptions = censusMeta.parameters;

// Map classification options.
export const CLASSIFICATION_OPTIONS = [5, 3];
export const DEFAULT_CLASSIFICATION = 5;

