// Parameter shown on first load and after the map reset button.
export const DEFAULT_PARAM_KEY = "households";

export const DEFAULT_RAMP_ID = "yellows";

// Fixed classification boundaries.
const classificationBreaks = {
  5: [
    { label: "< 10,00,000", min: 0, max: 1000000 },
    { label: "10,00,000 – 50,00,000", min: 1000000, max: 5000000 },
    { label: "50,00,000 – 1,00,00,000", min: 5000000, max: 10000000 },
    { label: "1,00,00,000 – 2,00,00,000", min: 10000000, max: 20000000 },
    { label: "> 2,00,00,000", min: 20000000, max: Infinity },
  ],
  3: [
    { label: "< 50,00,000", min: 0, max: 5000000 },
    { label: "50,00,000 – 2,00,00,000", min: 5000000, max: 20000000 },
    { label: "> 2,00,00,000", min: 20000000, max: Infinity },
  ],
};

// Expand compact census data into objects.
const expand = ({ keys, rows }) =>
  rows.map((row) =>
    Object.fromEntries(keys.map((key, index) => [key, row[index]])),
  );

const stateData = expand(stateCensus);
const districtData = expand(districtCensus);

// The parameter a figure is a share of, or null when it is a top-level total.
// Male / Female figures are a share of their total (Male Workers -> Total Workers),
// and each total (Workers, SC, ST, Literates...) is a share of the population.
// Rural / Urban figures are compared with the same figure for the whole area.
export function getParentKey(key) {
  const k = String(key || "");
  const prefix = k.startsWith("rural_")
    ? "rural_"
    : k.startsWith("urban_")
      ? "urban_"
      : "";
  const base = prefix ? k.slice(prefix.length) : k;

  if (base === "total_population" || base === "households") {
    return prefix ? base : null; // Rural / Urban parts compare with the whole
  }
  if (base === "male_population" || base === "female_population") {
    return `${prefix}total_population`;
  }

  let m = base.match(/^(child|sc|st)_(male|female)$/);
  if (m) return `${prefix}${m[1]}_population`;

  m = base.match(/^(literate|illiterate)_(male|female)$/);
  if (m) return `${prefix}${m[1]}s`;

  m = base.match(/^workers_(male|female)$/);
  if (m) return `${prefix}workers`;

  if (
    [
      "child_population",
      "sc_population",
      "st_population",
      "literates",
      "illiterates",
      "workers",
    ].includes(base)
  ) {
    return `${prefix}total_population`;
  }

  return null;
}

// Format numbers using the Indian numbering system.
export function formatIN(num) {
  if (
    num === null ||
    num === undefined ||
    num === "" ||
    !Number.isFinite(Number(num))
  ) {
    return "—";
  }

  return Math.round(Number(num)).toLocaleString("en-IN");
}

// Build fixed colour ranges.
function buildRanges(count, rampId) {
  const ramp = COLOR_RAMPS.find((item) => item.id === rampId) || COLOR_RAMPS[0];

  const colors =
    count === 3
      ? [ramp.colors[0], ramp.colors[2], ramp.colors[4]]
      : ramp.colors;

  return (classificationBreaks[count] || classificationBreaks[5]).map(
    (range, index) => ({
      id: `c${count}-${index + 1}`,
      ...range,
      color: colors[index],
    }),
  );
}

const populationRanges = buildRanges(DEFAULT_CLASSIFICATION, DEFAULT_RAMP_ID);

// Get classification ranges for a selected colour ramp.
export function getClassificationRanges(
  count = DEFAULT_CLASSIFICATION,
  rampId = DEFAULT_RAMP_ID,
) {
  return buildRanges(count, rampId);
}

// Return State / UT records.
export function getStateData() {
  return stateData;
}

// Return District records.
export function getDistrictData() {
  return districtData;
}

// Return the total number of State / UT records.
export function getStateCount() {
  return stateData.length;
}

// Return the total number of District records.
export function getDistrictCount() {
  return districtData.length;
}

// Return dashboard parameter options.
export function getParameters() {
  return parameterOptions;
}

// Return population legend ranges.
export function getPopulationRanges() {
  return populationRanges;
}

// Build data-based classification ranges.
export function getDataRanges(
  values,
  count = DEFAULT_CLASSIFICATION,
  rampId = DEFAULT_RAMP_ID,
) {
  const nums = (values || [])
    .map((value) =>
      value === null || value === undefined || value === ""
        ? NaN
        : Number(value),
    )
    .filter((value) => Number.isFinite(value) && value >= 0)
    .sort((a, b) => a - b);

  const fixed = buildRanges(count, rampId);

  if (nums.length < count * 2) {
    return fixed;
  }

  const round2 = (value) => {
    if (value < 100) return Math.round(value);

    const magnitude = 10 ** (Math.floor(Math.log10(value)) - 1);

    return Math.round(value / magnitude) * magnitude;
  };

  const cuts = [];

  for (let index = 1; index < count; index += 1) {
    const quantile =
      nums[
        Math.min(nums.length - 1, Math.floor((nums.length * index) / count))
      ];

    const cut = round2(quantile);

    if (cut > (cuts[cuts.length - 1] ?? 0)) {
      cuts.push(cut);
    }
  }

  if (cuts.length === 0) {
    return fixed;
  }

  const ramp = COLOR_RAMPS.find((item) => item.id === rampId) || COLOR_RAMPS[0];

  const allColors =
    count === 3
      ? [ramp.colors[0], ramp.colors[2], ramp.colors[4]]
      : ramp.colors;

  const colors = allColors.slice(0, cuts.length + 1);

  return [0, ...cuts].map((min, index) => {
    const max = cuts[index] ?? Infinity;

    const label =
      index === 0
        ? `< ${formatIN(max)}`
        : max === Infinity
          ? `> ${formatIN(min)}`
          : `${formatIN(min)} – ${formatIN(max)}`;

    return {
      id: `d${count}-${index + 1}`,
      label,
      min,
      max,
      color: colors[index],
    };
  });
}

// Classification ranges for a dataset the user uploaded. Unlike the census
// parameters it has no known scale, so the classes come only from its own
// values (quantiles), however few they are, and they keep decimals.
export function getCustomRanges(
  values,
  count = DEFAULT_CLASSIFICATION,
  rampId = DEFAULT_RAMP_ID,
) {
  const nums = (values || [])
    .map((value) =>
      value === null || value === undefined || value === ""
        ? NaN
        : Number(value),
    )
    .filter((value) => Number.isFinite(value) && value >= 0)
    .sort((a, b) => a - b);

  if (nums.length === 0) return [];

  const ramp = COLOR_RAMPS.find((item) => item.id === rampId) || COLOR_RAMPS[0];
  const allColors =
    count === 3
      ? [ramp.colors[0], ramp.colors[2], ramp.colors[4]]
      : ramp.colors;

  // Three significant digits keep cut points tidy without losing small values.
  const tidy = (value) => (value === 0 ? 0 : Number(value.toPrecision(3)));
  const fmt = (value) =>
    Number.isInteger(value) || Math.abs(value) >= 100
      ? formatIN(value)
      : String(Number(value.toFixed(2)));

  const cuts = [];

  for (let index = 1; index < count; index += 1) {
    const quantile =
      nums[
        Math.min(nums.length - 1, Math.floor((nums.length * index) / count))
      ];
    const cut = tidy(quantile);

    if (cut > (cuts[cuts.length - 1] ?? nums[0])) {
      cuts.push(cut);
    }
  }

  // Every value is the same: one class.
  if (cuts.length === 0) {
    return [
      {
        id: `u${count}-1`,
        label: fmt(nums[0]),
        min: 0,
        max: Infinity,
        color: allColors[Math.floor(allColors.length / 2)],
      },
    ];
  }

  const colors = allColors.slice(0, cuts.length + 1);

  return [0, ...cuts].map((min, index) => {
    const max = cuts[index] ?? Infinity;

    return {
      id: `u${count}-${index + 1}`,
      label:
        index === 0
          ? `< ${fmt(max)}`
          : max === Infinity
            ? `> ${fmt(min)}`
            : `${fmt(min)} – ${fmt(max)}`,
      min,
      max,
      color: colors[index],
    };
  });
}

// Find the matching range for a numeric value.
export function getRangeForValue(value, ranges = populationRanges) {
  if (
    value === null ||
    value === undefined ||
    value === "" ||
    !Number.isFinite(Number(value))
  ) {
    return null;
  }

  const numericValue = Number(value);

  if (numericValue < 0) {
    return null;
  }

  return (
    ranges.find(
      (range) => numericValue >= range.min && numericValue < range.max,
    ) ?? null
  );
}
